use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let text = input["input"]["text"].as_str().unwrap();
    let shift = input["input"]["shift"].as_i64().unwrap();
    let mut result = String::new();
    for c in text.chars() {
        if c.is_lowercase() {
            let offset = c as u8 - 'a' as u8;
            let new_offset = (offset + shift) % 26 + 'a' as u8;
            result.push(new_offset as char);
        } else {
            result.push(c);
        }
    }
    result
}

fn main() {
    let input = serde_json::Value::from("{\"input\":{\"text\":\"xyz A!\",\"shift\":3}}");
    let expected = serde_json::Value::from("{\"input\":{\"text\":\"abc A!\",\"shift\":3}}");
    assert_eq!(solve(input), expected);
}
```

